1	package water
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10		"time"
11	)
12	
13	// 本文件保护“打开本地数据”时的记录完整性校验：
14	// 每份样品的原测量中同一个项目名只能出现一次，这条规则对任何状态的样品都生效，
15	// 包括没有逐项判定的待判定样品，以及待判定后直接作废、没有历史判定依据的样品；
16	// 重复按保存的完整项目名判断，不靠相邻、不因同值（含两个零）放行。
17	// 带结论的样品还要求原测量项目与逐项判定按项目名完整一一对应、且对应项目的
18	// 测量值一致；缺项、多项、判定项目重复、测量值对不上（零也是合法测量值）或
19	// 整份样品没有测量项目，都必须让整次 Open 失败，返回 nil 存放，错误信息点到
20	// 具体样品编号与项目，且不覆盖原文件、不静默跳过、不择一保留或合并重复测量、
21	// 不补判定、不改成待判定。超标标记还必须与这份样品已保存的判定依据一致：
22	// 每条判定测量值严格大于其保存的上限才应为超标，小于或等于（含等于、零或负数
23	// 组合）都应为达标；整份标记必须与逐项结论一致，任一超标即为真、全部达标即为
24	// 假。单项标记相反，或单项都对而整份标记相反，都让整次 Open 失败；不修正标记、
25	// 不按当前限值重做判定。待判定样品、待判定后作废（无历史依据）的样品在原测量
26	// 不重复时不受影响；已确认后作废但历史依据完整且标记一致的样品继续兼容。
27	
28	const (
29		openPH   = "pH"
30		openTurb = "浊度"
31	)
32	
33	func openEff() time.Time { return at(1, 0) }
34	
35	// writeDiskFile 手工写入一份数据文件，便于构造正常流程不会产生的损坏记录。
36	func writeDiskFile(t *testing.T, dir string, st diskState) {
37		t.Helper()
38		data, err := json.MarshalIndent(st, "", "  ")
39		if err != nil {
40			t.Fatalf("marshal data file: %v", err)
41		}
42		if err := os.WriteFile(filepath.Join(dir, "water-data.json"), data, 0o644); err != nil {
43			t.Fatalf("write data file: %v", err)
44		}
45	}
46	
47	func openPoints() map[string]SamplingPoint {
48		return map[string]SamplingPoint{"P1": {ID: "P1", Name: "一号取水口"}}
49	}
50	
51	// phTurbResults 是与 pH 9、浊度 4 的原测量完整对应的两条判定，
52	// 排列顺序故意与测量相反，用来证明按项目名对应而非按位置对应。
53	func phTurbResults() []ItemResult {
54		return []ItemResult{
55			{Item: openTurb, Value: 4, Limit: 4, LimitEffective: openEff(), Exceeded: false},
56			{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
57		}
58	}
59	
60	func phTurbMeasurements() []Measurement {
61		return []Measurement{
62			{Item: openPH, Value: 9},
63			{Item: openTurb, Value: 4},
64		}
65	}
66	
67	// assertOpenRejects 断言打开整次失败：返回 nil 存放、错误可识别为
68	// ErrCorruptRecord，且信息包含出问题的样品编号与项目（noItem 为 true 时
69	// 只要求编号），原文件字节不被改动。
70	func assertOpenRejects(t *testing.T, dir, sampleID, itemHint string, noItem bool) {
71		t.Helper()
72		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
73		if err != nil {
74			t.Fatalf("read file before open: %v", err)
75		}
76		got, err := Open(dir)
77		if err == nil {
78			if got != nil {
79				got.Close()
80			}
81			t.Fatalf("损坏数据必须让整次 Open 失败，sample=%s", sampleID)
82		}
83		if got != nil {
84			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
85		}
86		if !errors.Is(err, ErrCorruptRecord) {
87			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
88		}
