1	package water
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// 本文件保护“打开本地数据”时对样品采样时间的完整性核对：每份样品都必须保留
13	// 采样时间。sampledAt 字段缺失、保存为 null 或明确保存为 Go 零时间
14	// 0001-01-01T00:00:00Z，JSON 反序列化后都是零时间，一律视为缺少采样时间。
15	// 这条要求适用于待判定、已确认和已作废的全部样品：作废前是否确认过、是否仍有
16	// 逐项判定都不影响；测量项目和数值完整，或者保留了相互一致的达标、超标依据，
17	// 也不能代替日期。只要文件里有一份样品缺少采样时间，整次 Open 就失败、返回
18	// nil 存放、错误可识别为 ErrCorruptRecord，信息点到具体样品编号并说明缺少的是
19	// 样品的采样时间（与登记限值或判定依据缺少生效时间相区分）；同一文件中其他样品
20	// 正常也不只读入正常部分，拒绝时原文件字节不变，不补日期、不猜日期、不改变样品
21	// 状态或已有结论。已确认记录缺日期时必须明确报告日期缺失，不能只说某项上限晚于
22	// 采样时间。完整日期按真实时刻继续使用，空数据照常打开。
23	
24	// assertOpenRejectsMissingSampledAt 断言打开因某份样品缺少采样时间而整次失败：
25	// 返回 nil 存放、ErrCorruptRecord，信息点名样品编号并说明缺少样品的采样时间
26	// （带出 sampledAt 字段名），且不能退化成“上限生效时间晚于采样时间”的说法；
27	// 原文件字节不被改动。
28	func assertOpenRejectsMissingSampledAt(t *testing.T, dir, sampleID string) {
29		t.Helper()
30		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
31		if err != nil {
32			t.Fatalf("read file before open: %v", err)
33		}
34		got, err := Open(dir)
35		if err == nil {
36			if got != nil {
37				got.Close()
38			}
39			t.Fatalf("缺少采样时间的样品必须让整次 Open 失败，sample=%s", sampleID)
40		}
41		if got != nil {
42			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
43		}
44		if !errors.Is(err, ErrCorruptRecord) {
45			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
46		}
47		msg := err.Error()
48		if !strings.Contains(msg, sampleID) {
49			t.Fatalf("错误信息应指出样品编号 %q，实际 %q", sampleID, msg)
50		}
51		for _, want := range []string{"采样时间", "sampledAt"} {
52			if !strings.Contains(msg, want) {
53				t.Fatalf("错误信息应明确说明缺少样品的采样时间（含 %q），实际 %q", want, msg)
54			}
55		}
56		// 哨兵错误自身的说明里带有“晚于采样时间”字样，因此只检查去掉哨兵前缀后的
57		// 具体原因：采样时间本身缺失时必须明确报日期缺失，不能退化成某项上限晚于
58		// 采样时间的说法。
59		detail := strings.TrimPrefix(msg, ErrCorruptRecord.Error())
60		if strings.Contains(detail, "晚于采样时间") {
61			t.Fatalf("采样时间本身缺失时必须明确报告日期缺失，不能只说上限晚于采样时间：%q", msg)
62		}
63		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
64		if rerr != nil {
65			t.Fatalf("read file after open: %v", rerr)
66		}
67		if string(after) != string(before) {
68			t.Fatalf("打开失败不得覆盖或改写原数据文件")
69		}
70	}
71	
72	// 三种缺日期写法（字段缺失、null、Go 零时间）对待判定样品都必须整次拒绝。
73	// 直接写原始 JSON 覆盖字段缺失与 null 两种 Go 结构体序列化表达不出的形态。
74	func TestOpenPendingMissingSampledAtForms(t *testing.T) {
75		cases := []struct {
76			name string
77			raw  string
78		}{
79			{
