// 任一处编号带首尾空白都不能整理后放行，即使两处去掉空白后相同；分别覆盖
// 只有集合键带空白、只有记录 id 带空白、两处都带空白三种情况。
func TestOpenIDWithSurroundingWhitespaceRejected(t *testing.T) {
	cases := []struct {
		name    string
		keyText string
		idToken string
	}{
		{"集合键带空白", `" S1 "`, `"id":"S1"`},
		{"记录id带空白", `"S1"`, `"id":" S1 "`},
